import ast

import sqlparse


def _python(sql, **kwargs):
    return sqlparse.format(sql, output_format='python', **kwargs)


def _php(sql, **kwargs):
    return sqlparse.format(sql, output_format='php', **kwargs)


class TestOutputPythonBackslash:
    def test_backslash_in_string_literal(self):
        sql = r"select 'a\b'"
        assert _python(sql) == r"sql = 'select \'a\\b\''"

    def test_double_backslash_in_string_literal(self):
        sql = r"select 'a\\b'"
        assert _python(sql) == r"sql = 'select \'a\\\\b\''"

    def test_backslash_in_double_quoted_identifier(self):
        # no single quote in the token, only a backslash
        sql = r'select "a\b" from foo'
        assert _python(sql) == r"""sql = 'select "a\\b" from foo'"""

    def test_backslash_outside_of_quotes(self):
        sql = 'select 1 \\ 2'
        assert _python(sql) == r"sql = 'select 1 \\ 2'"

    def test_output_evaluates_to_original_sql(self):
        sql = r"select 'C:\new\table', 'it''s' from foo"
        out = _python(sql)
        assert out.startswith('sql = ')
        assert ast.literal_eval(out[len('sql = '):]) == sql

    def test_backslash_multiline(self):
        sql = r"select 'a\b' from foo"
        assert _python(sql, reindent=True) == '\n'.join([
            r"sql = ('select \'a\\b\' '",
            "       'from foo')"])


class TestOutputPHPBackslash:
    def test_backslash_in_string_literal(self):
        sql = r"select 'a\b'"
        assert _php(sql) == r'''$sql = "select 'a\\b'";'''

    def test_double_backslash_in_string_literal(self):
        sql = r"select 'a\\b'"
        assert _php(sql) == r'''$sql = "select 'a\\\\b'";'''

    def test_backslash_and_double_quote(self):
        # the backslash added for the quote must not be escaped again
        sql = r'select "a\b" from foo'
        assert _php(sql) == r'$sql = "select \"a\\b\" from foo";'

    def test_backslash_outside_of_quotes(self):
        sql = 'select 1 \\ 2'
        assert _php(sql) == r'$sql = "select 1 \\ 2";'

    def test_backslash_multiline(self):
        sql = r"select 'a\b' from foo"
        assert _php(sql, reindent=True) == '\n'.join([
            r'''$sql  = "select 'a\\b' ";''',
            '$sql .= "from foo";'])

